package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class PercentAmountRelationsTest {
 @Test public void allAmountsIncludeFifteenPercentOf360AndPublicPoisonedHelp(){for(int i=0;i<101101;i++){Question q=PercentAmountRelations.at("percent",i);var v=PercentAmountRelations.readAmount(q);Rational expected=Rational.of(v.base()*v.percent(),100);assertTrue(new Checker().check(q,List.of(),List.of(expected.decimalText())).correct());q.expression="poison";q.answers=new String[]{"999"};HelpPlan h=HelpPlan.forQuestion(q);assertEquals(4,h.size());assertFalse(h.canTransfer());List<String> values=List.of(""+v.base(),""+v.percent(),Rational.of(v.percent(),100).toString(),expected.toString());for(int j=0;j<4;j++)assertTrue(h.step(j).accepts(values.get(j)));}assertEquals("54",PercentAmountRelations.amount(360,15).answers[0]);}
 @Test public void allComparisonConditionsUseAmountsNotBareRates(){boolean opposite=false;Set<String> signs=new HashSet<>();for(int i=0;i<1020100;i++){Question q=PercentAmountRelations.at(PercentAmountRelations.COMPARE,i);int[] v=PercentAmountRelations.readCompare(q);int cmp=Integer.compare(v[0]*v[1],v[2]*v[3]);String expected=cmp<0?"<":cmp>0?">":"=";signs.add(expected);opposite|=v[1]>v[3]&&cmp<0;assertEquals(expected,q.answers[0]);assertTrue(new Checker().check(q,List.of(),List.of(expected)).correct());}assertTrue(opposite);assertEquals(Set.of("<","=",">"),signs);Question q=PercentAmountRelations.compare(10,90,100,10);q.answers=new String[]{">"};q.expression="poison";HelpPlan h=HelpPlan.forQuestion(q);assertEquals(9,h.size());assertFalse(h.canTransfer());List<String> inputs=List.of("10","90","0.9","9","100","10","0.1","10","<");for(int i=0;i<9;i++){assertTrue(h.step(i).accepts(inputs.get(i)));assertEquals("",h.step(i).after);}assertFalse(h.step(8).accepts(">"));}
 @Test public void gradeLinksFreshSupplyAndExistingDraftVersion(){var pack=GlobalCurriculum.packs("GB").stream().filter(x->x.id.equals("england-primary-2021-v1")).findFirst().orElseThrow();Generator g=new Generator(new Random(99));for(String id:List.of("percent",PercentAmountRelations.COMPARE)){assertTrue(pack.inGrade(id,6));List<String> recent=new ArrayList<>();for(int i=0;i<150;i++){Question q=g.next(id,recent,false,GlobalCurriculum.limits(pack.id,id,6));assertFalse(recent.contains(q.signature()));recent.add(q.signature());}}Question q=PercentAmountRelations.amount(30,5);assertEquals("ratio-value-relations-v1",q.studyGuide.teachingVersion);Learning.Profile profile=new Learning.Profile();profile.countryCode="KR";profile.educationSystem="kr-national";assertTrue(GlobalCurriculum.available(profile).stream().noneMatch(s->s.id.equals(PercentAmountRelations.COMPARE)));}
}
